const p = await tools.update_plan({plan:[
  {step:"Inspect applicable review instructions and repository guidance",status:"in_progress"},
  {step:"Analyze the diff and affected call sites",status:"pending"},
  {step:"Run focused tests or checks for candidate defects",status:"pending"},
  {step:"Return prioritized JSON findings",status:"pending"}
]}); text(p)

const cmds = [
  ["memory", "rg -n \"Owletto|mcp-app|ChatGPT|rehydrat|code review|review\" /Users/burakemre/.codex/memories/MEMORY.md | head -80", "/Users/burakemre/Code/lobu/.claude/worktrees/mcp-app-chatgpt-rehydrate/packages/owletto"],
  ["skill", "sed -n '1,240p' /Users/burakemre/.agents/skills/lobu-operator/SKILL.md", "/Users/burakemre/Code/lobu/.claude/worktrees/mcp-app-chatgpt-rehydrate/packages/owletto"],
  ["repo", "printf '%s\\n' '--- status ---'; git status --short; printf '%s\\n' '--- root ---'; git rev-parse --show-toplevel; printf '%s\\n' '--- instruction files ---'; find .. -name AGENTS.md -o -name AGENTS.override.md 2>/dev/null | sort; printf '%s\\n' '--- diff stat ---'; git diff --stat 26a0bfac8698b4544d766ef2427513b04e14e14c; printf '%s\\n' '--- changed ---'; git diff --name-status 26a0bfac8698b4544d766ef2427513b04e14e14c", "/Users/burakemre/Code/lobu/.claude/worktrees/mcp-app-chatgpt-rehydrate/packages/owletto"]
];
const rs = await Promise.all(cmds.map(async ([label,cmd,workdir]) => [label, await tools.exec_command({cmd,workdir,yield_time_ms:10000,max_output_tokens:20000})]));
for (const [label,r] of rs) { text(`### ${label}\n${r.output}`); }

const r = await tools.exec_command({
  cmd: "printf '%s\\n' '--- top files ---'; ls -la | sed -n '1,160p'; printf '%s\\n' '--- guidance candidates ---'; find . -maxdepth 4 \\( -name AGENTS.md -o -name AGENTS.override.md -o -name CLAUDE.md -o -name GOTCHAS.md \\) -print | sort; printf '%s\\n' '--- parent guidance ---'; for f in ../../AGENTS.override.md ../../AGENTS.md ../../CLAUDE.md ../../../AGENTS.override.md ../../../AGENTS.md ../../../CLAUDE.md; do if test -f \"$f\"; then echo \"### $f\"; sed -n '1,240p' \"$f\"; fi; done; printf '%s\\n' '--- local guidance ---'; for f in AGENTS.override.md AGENTS.md CLAUDE.md docs/GOTCHAS.md; do if test -f \"$f\"; then echo \"### $f\"; sed -n '1,260p' \"$f\"; fi; done",
  workdir: "/Users/burakemre/Code/lobu/.claude/worktrees/mcp-app-chatgpt-rehydrate/packages/owletto",
  yield_time_ms: 10000,
  max_output_tokens: 30000
}); text(r.output)

const r = await tools.exec_command({
  cmd: "git diff --find-renames --find-copies --minimal 26a0bfac8698b4544d766ef2427513b04e14e14c -- scripts/check-mcp-app-bundle.mjs src/mcp-apps/_shared/host.tsx src/mcp-apps/_shared/openai-compat.ts src/mcp-apps/_shared/host.test.tsx src/mcp-apps/_shared/openai-compat.test.ts",
