    15	import { isExternalHttpUrl } from "./view";
    16	
    17	/** Shared iframe-side runtime for every Lobu MCP App bundle. */
    18	
    19	type ToolArgs = Record<string, unknown>;
    20	
    21	interface McpAppApi<T> {
    22		/** Server-authored LobuViewV1 from the originating tool result. */
    23		data: T | null;
    24		/** Ask the host to broker a standard MCP `tools/call`. */
    25		callTool: (name: string, args: ToolArgs) => Promise<void>;
    26		/** Ask the host to open an external URL via `ui/open-link`. */
    27		openLink: (href: string) => Promise<void>;
    28		/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
    29		lastResult: { isError: boolean; seq: number } | null;
