    34	const McpAppContext = createContext<McpAppApi<unknown>>({
    35		data: null,
    36		callTool: async () => {},
    37		openLink: async () => {},
    38		lastResult: null,
    39		allowSpaHostedViews: false,
    40	});
    41	
    42	/** Typed accessor for the host bridge inside a bundle's card component. */
    43	export function useMcpApp<T>(): McpAppApi<T> {
    44		return useContext(McpAppContext) as McpAppApi<T>;
    45	}
    46	
    47	const isEmbedded = window.parent !== window;
    48	const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";
    49	
    50	type OpenAiCompatWindow = Window & { openai?: unknown };
    51	type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;
    52	
    53	function openAiCompatTargets(): OpenAiCompatWindow[] {
    54		const ownWindow = window as OpenAiCompatWindow;
    55		if (!isEmbedded) return [ownWindow];
    56		try {
    57			if (window.parent.location.origin === window.location.origin) {
    58				return [ownWindow, window.parent as OpenAiCompatWindow];
    59			}
    60		} catch {
    61			// A cross-origin parent is the standard portable MCP Apps topology.
    62		}
    63		return [ownWindow];
    64	}
    65	
    66	function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
    67		let fallback: unknown;
    68		for (const target of targets) {
    69			const candidate = target.openai;
    70			if (candidate === undefined) continue;
    71			fallback ??= candidate;
    72			if (
    73				isStructuredObject(candidate) &&
    74				(Object.hasOwn(candidate, "toolOutput") ||
    75					Object.hasOwn(candidate, "toolResponseMetadata"))
    76			) {
    77				return candidate;
    78			}
    79		}
    80		return fallback;
    81	}
    82	
    83	function hasSameOriginParent(): boolean {
    84		if (!isEmbedded) return true;
    85		try {
    86			return window.parent.location.origin === window.location.origin;
    87		} catch {
    88			return false;
    89		}
    90	}
    91	
    92	function isStructuredObject(value: unknown): value is Record<string, unknown> {
    93		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
    94	}
    95	
    96	function applyTheme(theme: "light" | "dark" | undefined): void {
    97		const dark = theme
    98			? theme === "dark"
    99			: window.matchMedia("(prefers-color-scheme: dark)").matches;
   100		document.documentElement.classList.toggle("dark", dark);
   101	}
   102	
   103	export function Provider<T>({
   104		devMock,
   105		children,
   106	}: {
   107		devMock: T;
   108		children: ReactNode;
   109	}) {
   110		const [initialCompat] = useState(() =>
   111			readOpenAiCompatSnapshot<T>(currentOpenAiGlobals()),
   112		);
   113		const [data, setData] = useState<T | null>(
   114			isEmbedded ? (initialCompat.data ?? null) : devMock,
   115		);
