   117			isError: boolean;
   118			seq: number;
   119		} | null>(null);
   120		const [app, setApp] = useState<App | null>(null);
   121		const [approvalCapability, setApprovalCapability] = useState<string | null>(
   122			initialCompat.approvalCapability ?? null,
   123		);
   124		const allowSpaHostedViews = hasSameOriginParent();
   125	
   126		useEffect(() => {
   127			if (!isEmbedded) {
   128				applyTheme(undefined);
   129				return;
   130			}
   131	
   132			const compatTargets = openAiCompatTargets();
   133			const nextApp = new App(
   134				{ name: "Lobu Interaction", version: "1.0.0" },
   135				{},
   136				{ autoResize: true, strict: true },
   137			);
   138			const transport = new PostMessageTransport(window.parent, window.parent);
   139			const onToolResult = (params: {
   140				structuredContent?: unknown;
   141				_meta?: unknown;
   142			}) => {
   143				if (isStructuredObject(params.structuredContent)) {
   144					setData(params.structuredContent as T);
   145				}
   146				setApprovalCapability(approvalCapabilityFromMeta(params._meta));
   147			};
   148			const onHostContext = (params: { theme?: "light" | "dark" }) =>
   149				applyTheme(params.theme);
   150			const applyOpenAiGlobals = (globals: unknown) => {
   151				const snapshot = readOpenAiCompatSnapshot<T>(globals);
   152				if (snapshot.data !== undefined) setData(snapshot.data);
   153				if (snapshot.approvalCapability !== undefined) {
   154					setApprovalCapability(snapshot.approvalCapability);
   155				}
   156			};
   157			const onOpenAiSetGlobals = (event: Event) => {
   158				const detail = (event as OpenAiSetGlobalsEvent).detail;
   159				if (isStructuredObject(detail) && "globals" in detail) {
   160					applyOpenAiGlobals(detail.globals);
   161				}
   162			};
   163			nextApp.addEventListener("toolresult", onToolResult);
   164			nextApp.addEventListener("hostcontextchanged", onHostContext);
   165			for (const target of compatTargets) {
   166				target.addEventListener(OPENAI_SET_GLOBALS_EVENT, onOpenAiSetGlobals);
   167			}
   168			applyOpenAiGlobals(currentOpenAiGlobals(compatTargets));
   169			setApp(nextApp);
   170			void nextApp
   171				.connect(transport)
   172				.then(() => applyTheme(nextApp.getHostContext()?.theme))
   173				.catch((error) => {
   174					console.error("[mcp-app] failed to initialize", error);
   175				});
   176	
   177			return () => {
   178				nextApp.removeEventListener("toolresult", onToolResult);
   179				nextApp.removeEventListener("hostcontextchanged", onHostContext);
   180				for (const target of compatTargets) {
   181					target.removeEventListener(
   182						OPENAI_SET_GLOBALS_EVENT,
   183						onOpenAiSetGlobals,
   184					);
   185				}
   186				void transport.close();
   187			};
   188		}, []);
   189	
   190		const callTool = async (name: string, args: ToolArgs) => {
   191			if (!app) {
   192				if (!isEmbedded) {
   193					console.log("[mcp-app] tools/call", name, args);
   194					setLastResult((last) => ({
   195						isError: false,
   196						seq: (last?.seq ?? 0) + 1,
   197					}));
   198				}
   199				return;
   200			}
   201			try {
   202				const result = await app.callServerTool({
   203					name,
   204					arguments: args,
   205					...(name === "resolve_lobu_approval" && approvalCapability
   206						? { _meta: { "lobu/approval-capability": approvalCapability } }
   207						: {}),
   208				});
   209				if (isStructuredObject(result.structuredContent)) {
   210					setData(result.structuredContent as T);
   211				}
   212				if (name === "resolve_lobu_approval" && result.isError !== true) {
   213					setApprovalCapability(null);
   214				}
   215				setLastResult((last) => ({
   216					isError: result.isError === true,
   217					seq: (last?.seq ?? 0) + 1,
   218				}));
   219			} catch {
   220				setLastResult((last) => ({
   221					isError: true,
   222					seq: (last?.seq ?? 0) + 1,
   223				}));
   224			}
   225		};
   226	
   227		const openLink = async (href: string) => {
   228			if (!isExternalHttpUrl(href)) {
   229				console.warn("[mcp-app] refused non-HTTP external link");
   230				return;
   231			}
   232			if (!app) {
   233				if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
   234				return;
   235			}
   236			try {
   237				const result = await app.openLink({ url: href });
   238				if (result.isError) console.warn("[mcp-app] host rejected external link");
   239			} catch {
   240				console.warn("[mcp-app] host rejected external link");
   241			}
   242		};
   243	
   244		return (
   245			<McpAppContext.Provider
   246				value={{ data, callTool, openLink, lastResult, allowSpaHostedViews }}
   247			>
   248				{children}
   249			</McpAppContext.Provider>
   250		);
   251	}
   252	
   253	/** Mount a bundle's card as a standalone MCP App with the standard bridge. */
   254	export function mountMcpApp<T>(opts: { devMock: T; App: FC }): void {
   255		const { devMock, App: View } = opts;
   256		createRoot(document.getElementById("root") as HTMLElement).render(
   257			<Provider devMock={devMock}>
   258				<View />
   259			</Provider>,
   260		);
   261	}
